content.solution_code:
class Tool {
  constructor(name) {
    this.name = name;
  }

  use() {
    return `${this.name} is being used.`;
  }
}

class Hammer extends Tool {
  constructor(name, weight) {
    super(name);
    this.weight = weight;
  }

  // Private helper method to encapsulate hammer's specific action
  #strikeAction() {
    return `striking with ${this.weight}kg impact`;
  }

  use() {
    // Call the parent's use method and combine with hammer's specific action
    return `${super.use()} and ${this.#strikeAction()}.`;
  }
}

